import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Plateaus","description":"","frontmatter":{"title":"Plateaus","covers":{"screens":["SCR-065"],"stories":["US-084","US-085","US-089","US-155"]}},"headers":[],"relativePath":"de/usage/plateaus.md","filePath":"de/usage/plateaus.md"}`),a={name:`de/usage/plateaus.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="plateaus" tabindex="-1">Plateaus <a class="header-anchor" href="#plateaus" aria-label="Permalink to “Plateaus”">​</a></h1><p>Ein Plateau ist ein benannter, stabiler Zustand deiner Architektur. Die <strong>Baseline</strong> ist die Architektur, die heute im Betrieb ist. <strong>Ziel-</strong> und <strong>Übergangsplateaus</strong> beschreiben geplante Zustände: einen Zielzustand und Zwischenstände auf dem Weg dorthin. <a href="./solutions">Lösungen</a> können auf ein Plateau hinarbeiten.</p><p>Für den Plateaumodus gibt es keinen Schalter: Er beginnt, wenn du die erste Baseline anlegst. Lösungen ohne Plateau arbeiten weiter wie bisher.</p><p>Zum Anlegen und Bearbeiten von Plateaus brauchst du die Berechtigung <code>plateau:write</code> (zum Beispiel die Rolle <code>enterprise-architect</code>). Um sie zu sehen, reicht <code>plateau:write</code>, <code>plateau:go-live</code> oder <code>solution:write</code> (siehe <a href="./../administration/roles-and-permissions">Rollen und Berechtigungen</a>).</p><h2 id="die-seite-plateaus" tabindex="-1">Die Seite Plateaus <a class="header-anchor" href="#die-seite-plateaus" aria-label="Permalink to “Die Seite Plateaus”">​</a></h2><p>Wähle in der Kopfzeile <em>Plateaus</em>. Die Seite zeigt:</p><ul><li>die <strong>Baseline</strong>, hervorgehoben, mit dem Datum, seit dem sie gilt;</li><li>die <strong>Ziel- und Übergangsplateaus</strong>, nach geplantem Datum, jeweils mit Vorgänger, Basis und der Zahl der Lösungen, die darauf hinarbeiten. Gibt es keines, steht dort „Noch kein Zielplateau geplant“;</li><li>die <strong>realisierten Plateaus</strong>, eingeklappt, das neueste zuerst. Ein Plateau wird realisiert, wenn sein Nachfolger live geht.</li></ul><h2 id="die-initiale-baseline-anlegen" tabindex="-1">Die initiale Baseline anlegen <a class="header-anchor" href="#die-initiale-baseline-anlegen" aria-label="Permalink to “Die initiale Baseline anlegen”">​</a></h2><p>Ohne Baseline steht auf der Seite „Es gibt noch kein Baseline-Plateau“. Wähle <em>Initiale Baseline anlegen</em>, gib einen Namen wie „Baseline 2026-Q2“ und optional eine Beschreibung und das Datum des Stands ein und wähle <em>Plateau anlegen</em>. Es gibt immer nur eine Baseline.</p><h2 id="ein-ziel-oder-ubergangsplateau-anlegen" tabindex="-1">Ein Ziel- oder Übergangsplateau anlegen <a class="header-anchor" href="#ein-ziel-oder-ubergangsplateau-anlegen" aria-label="Permalink to “Ein Ziel- oder Übergangsplateau anlegen”">​</a></h2><ol><li><p>Wähle <em>Neues Plateau</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>Pflicht, bis 255 Zeichen, eindeutig unabhängig von Gross- und Kleinschreibung</td></tr><tr><td>Art</td><td><em>Ziel</em> oder <em>Übergang</em></td></tr><tr><td>Beschreibung</td><td>optional, bis 2000 Zeichen</td></tr><tr><td>Gültig ab</td><td>optional: das geplante Go-live-Datum</td></tr><tr><td>Vorgänger</td><td>das Plateau, auf das dieses folgt; die Baseline ist vorausgewählt. Ein realisiertes Plateau kann kein Vorgänger sein</td></tr><tr><td>Basis</td><td>wovon die Lösungen dieses Plateaus ausgehen (siehe unten)</td></tr></tbody></table></li><li><p>Wähle <em>Plateau anlegen</em>.</p></li></ol><h3 id="basis" tabindex="-1">Die Basis <a class="header-anchor" href="#basis" aria-label="Permalink to “Die Basis”">​</a></h3><p>Die Basis bestimmt, was eine Lösung, die auf das Plateau hinarbeitet, als ihre Ausgangslage sieht:</p><ul><li><strong>Aktueller Katalog:</strong> der Katalog, wie er jetzt ist.</li><li><strong>Inhalt des Vorgängers:</strong> das Vorgängerplateau mit den Änderungen seiner aktiven Lösungen. Eine Entität, die eine Lösung des Vorgängers ausser Betrieb nimmt, ist mit <em>Wird abgelöst durch …</em> markiert, eine neue Entität, die sie vorschlägt, mit <em>Vorgeschlagen von …</em>, und geänderte Namen und Werte zeigen ihren geplanten Wert. Eine vorgeschlagene Entität kann noch nicht geändert oder ausser Betrieb genommen werden, weil sie vor ihrem Go-live nicht existiert. Hat der Vorgänger selbst die Basis „Inhalt des Vorgängers“, zählt auch dessen Vorgänger.</li></ul><p>Ändern zwei Lösungen desselben Plateaus dasselbe Feld, zählt die zuletzt gemachte Änderung.</p><h2 id="ein-plateau-bearbeiten" tabindex="-1">Ein Plateau bearbeiten <a class="header-anchor" href="#ein-plateau-bearbeiten" aria-label="Permalink to “Ein Plateau bearbeiten”">​</a></h2><p>Wähle <em>Bearbeiten</em> neben einem Plateau, um Name, Beschreibung, Datum, Vorgänger oder Basis zu ändern. Die Art ändert sich nur durch das Go-live. Der Vorgänger ist fest, sobald eine Lösung auf das Plateau hinarbeitet.</p><p>Ein realisiertes Plateau ist schreibgeschützt: Es hat kein <em>Bearbeiten</em>, und die API antwortet „Realized plateau is read-only“.</p><h2 id="uber-die-api" tabindex="-1">Über die API <a class="header-anchor" href="#uber-die-api" aria-label="Permalink to “Über die API”">​</a></h2><p><code>GET /api/v1/plateaus</code> listet die Plateaus, <code>POST /api/v1/plateaus</code> legt eines an, und <code>GET</code> und <code>PUT /api/v1/plateaus/{id}</code> lesen und bearbeiten eines. Anlegen und Bearbeiten werden als <code>plateau.created</code> und <code>plateau.updated</code> protokolliert.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};